interface AgentTask {
    id: string;  // Simple agent-assigned identifier (e.g., "t1", "t2", "t3").
    title: string;  // Brief description of the work item.
    status: ''pending'' | ''in_progress'' | ''completed'' | ''blocked'';  // Current status of the task.
