-- Save MJ: Template Contents (core SP call only)
DECLARE @ID_1cb02c39 UNIQUEIDENTIFIER,
@TemplateID_1cb02c39 UNIQUEIDENTIFIER,
@TypeID_1cb02c39 UNIQUEIDENTIFIER,
@TemplateText_1cb02c39 NVARCHAR(MAX),
@Priority_1cb02c39 INT,
@IsActive_1cb02c39 BIT
SET
  @ID_1cb02c39 = '83ede897-66b9-41ab-92ab-f605b2fd8f63'
SET
  @TemplateID_1cb02c39 = '6153CD6F-1057-4A3D-892F-A6B4C96B045F'
SET
  @TypeID_1cb02c39 = 'E7AFCCEC-6A37-EF11-86D4-000D3A4E707E'
SET
  @TemplateText_1cb02c39 = N'You write a concise recap of a support conversation so that, when this visitor returns later and talks to the agent again, the agent opens with useful prior context. The recap is stored as an agent memory note and injected at the start of the next session.

Write a SHORT recap (2–5 sentences, no preamble) capturing only what helps a future conversation:
- who the visitor appears to be and what they were trying to do,
- key facts they shared (products, accounts, constraints, preferences) — but NEVER secrets, full payment details, or passwords,
- the outcome and any open/unresolved follow-up.

Write in the third person ("The visitor asked about…"). Do not invent details that are not in the transcript. Capture whatever the visitor said or asked — even a single topic or question is worth remembering so the agent can pick up where they left off. Reply with exactly NO_RECAP ONLY when the transcript is empty or contains nothing but a greeting (e.g. just "hi").

Conversation transcript:
{{ transcript }}
'
SET
  @Priority_1cb02c39 = 1
SET
  @IsActive_1cb02c39 = 1
EXEC [${flyway:defaultSchema}].spCreateTemplateContent @ID = @ID_1cb02c39,
  @TemplateID = @TemplateID_1cb02c39,
  @TypeID = @TypeID_1cb02c39,
  @TemplateText = @TemplateText_1cb02c39,
  @Priority = @Priority_1cb02c39,
  @IsActive = @IsActive_1cb02c39;

GO

