SET
  @IconClass_55a91c8b = N'fa-solid fa-globe'
SET
  @Color_55a91c8b = N'#2563EB'
SET
  @CreatedByUserID_55a91c8b = 'ECAFCCEC-6A37-EF11-86D4-000D3A4E707E'
SET
  @ActivationMode_55a91c8b = N'Auto'
SET
  @ID_55a91c8b = '6FBC5823-3418-4788-A75F-5AC6E0654DB1' EXEC [${flyway:defaultSchema}].spUpdateAISkill @Name = @Name_55a91c8b,
