  @Name_7c45ede6 = N'DataGrid'
SET
  @Version_7c45ede6 = N'1.0.0'
SET
  @VersionSequence_7c45ede6 = 1
SET
  @Title_7c45ede6 = N'Data Grid'
SET
  @Description_7c45ede6 = N'Flexible data grid component with its own simplified API. Accepts **data via props** (you manage data loading). Supports sorting, filtering, paging, row selection. Optional native record opening on row click (provide entityName + entityPrimaryKeys). Two column modes: simple (string array `[''Name'', ''Price'']`) or advanced (ColumnDef objects: `{field, header, render, width, sortable}`). Metadata-aware formatting: dates (locale with time), booleans (Yes/No), value lists (colored tags with 50+ status colors), money ($USD), decimals, integers (commas). Long text handling: truncate (ellipsis), expand (click ''show more/less''), tooltip (hover), wrap (word-break), none.

#### DataGrid - ONLY use when:
✅ You already have the data (from your own RunView call, aggregated query, joined tables, API response, etc.)
✅ You need custom data manipulation before display (filtering, transformation, merging multiple sources)
✅ You need full control over the data loading logic
✅ Displaying 2+ records in a list/table format
✅ Works with any array of objects (not just entity records)

❌ DO NOT USE DataGrid when:
- You want automatic entity record loading → **Use EntityDataGrid instead** (it calls RunView for you)
- Displaying a single record → **Use SingleRecordView instead**
- Need data visualization → **Use SimpleChart or SimpleDrilldownChart instead**
- Need automatic caching and pagination logic → **Use EntityDataGrid instead**

**Key difference from EntityDataGrid**: DataGrid is data-agnostic and passive (you pass data in). EntityDataGrid is entity-aware and active (it loads data via RunView). Choose DataGrid when you need control over data loading, EntityDataGrid for automatic entity record loading with smart caching.

**Row keys**: DataGrid assigns each row''s React key using this priority: `row.key` → `entityPrimaryKeys` (joined with `_`) → `row.ID` → `row.id` → `index`. When `entityPrimaryKeys` is provided, the primary key fields are used to build a unique key per row. For client-side joins where the output `ID` may not be unique, provide `entityPrimaryKeys` pointing to the field(s) that uniquely identify each row.
'
SET
  @Type_7c45ede6 = N'Table'
SET
  @Status_7c45ede6 = N'Published'
SET
  @Specification_7c45ede6 = N'{"name":"DataGrid","title":"Data Grid","description":"Flexible data grid component with its own simplified API. Accepts **data via props** (you manage data loading). Supports sorting, filtering, paging, row selection. Optional native record opening on row click (provide entityName + entityPrimaryKeys). Two column modes: simple (string array `[''Name'', ''Price'']`) or advanced (ColumnDef objects: `{field, header, render, width, sortable}`). Metadata-aware formatting: dates (locale with time), booleans (Yes/No), value lists (colored tags with 50+ status colors), money ($USD), decimals, integers (commas). Long text handling: truncate (ellipsis), expand (click ''show more/less''), tooltip (hover), wrap (word-break), none.\n\n#### DataGrid - ONLY use when:\n✅ You already have the data (from your own RunView call, aggregated query, joined tables, API response, etc.)\n✅ You need custom data manipulation before display (filtering, transformation, merging multiple sources)\n✅ You need full control over the data loading logic\n✅ Displaying 2+ records in a list/table format\n✅ Works with any array of objects (not just entity records)\n\n❌ DO NOT USE DataGrid when:\n- You want automatic entity record loading → **Use EntityDataGrid instead** (it calls RunView for you)\n- Displaying a single record → **Use SingleRecordView instead**\n- Need data visualization → **Use SimpleChart or SimpleDrilldownChart instead**\n- Need automatic caching and pagination logic → **Use EntityDataGrid instead**\n\n**Key difference from EntityDataGrid**: DataGrid is data-agnostic and passive (you pass data in). EntityDataGrid is entity-aware and active (it loads data via RunView). Choose DataGrid when you need control over data loading, EntityDataGrid for automatic entity record loading with smart caching.\n\n**Row keys**: DataGrid assigns each row''s React key using this priority: `row.key` → `entityPrimaryKeys` (joined with `_`) → `row.ID` → `row.id` → `index`. When `entityPrimaryKeys` is provided, the primary key fields are used to build a unique key per row. For client-side joins where the output `ID` may not be unique, provide `entityPrimaryKeys` pointing to the field(s) that uniquely identify each row.\n","type":"table","location":"embedded","functionalRequirements":"## Purpose\nDisplay tabular data with sorting, filtering, paging, and row selection. Data-agnostic component that accepts any array of objects via props (you manage data loading).\n\n## Data Requirements\n- **Input**: Array of objects passed via `data` prop\n- **Optional**: `entityName` for metadata-driven formatting\n- **Optional**: `entityPrimaryKeys` array for built-in record opening on row click\n\n## Column Configuration\n**Two modes supported:**\n\n1. **Simple mode** (backward compatible):\n   - String array of field names: `[''Name'', ''SKU'', ''Price'']`\n   - Uses smart defaults from metadata (DisplayName, Type for formatting/alignment)\n\n2. **Advanced mode** (full control):\n   - ColumnDef objects: `{field: ''Price'', header: ''Unit Price'', render: (value, record, fieldInfo) => JSX, width: ''120px'', sortable: true}`\n   - Custom render functions receive value, full record, and field metadata\n   - Per-column width and sortable overrides\n\n**Auto-detection**: If `columns` prop omitted, discovers fields from first data record (filters out ''key'' field).\n\n## Metadata-Aware Formatting\nWhen `entityName` provided, uses entity metadata for intelligent display:\n\n- **Dates**: Locale format with hour/minute (e.g., \"Jan 15, 2024, 3:30 PM\")\n- **Booleans**: \"Yes\" / \"No\" text\n- **Value Lists**: Colored Tag components with smart color assignment\n  - 50+ predefined status colors (active→green, pending→orange, failed→red, processing→blue)\n  - 50 fallback colors for other values\n  - Consistent color per value across dataset\n- **Money**: Intl.NumberFormat with $USD currency\n- **Decimals/Floats**: 2 decimal places with comma thousands separator\n- **Integers**: Comma thousands separator\n- **Right-alignment**: Numbers, money, bit fields automatically right-aligned\n\n## Long Text Handling\nFive modes for fields exceeding `longTextThreshold` (default 200 chars):\n\n1. **truncate**: Substring + ''...'' with ellipsis\n2. **expand** (default): Click to toggle ''show more/less'' (tracks expanded state per cell)\n3. **tooltip**: Full text on hover with Ant Tooltip\n4. **wrap**: Word-break normal, shows all text with wrapping\n5. **none**: Default browser behavior\n\n## Features\n\n### Sorting\n- Column-level sorting with string/number comparison\n- Click header to sort ascending/descending\n- Global `sorting` prop enables/disables all columns\n- Per-column `sortable` override in ColumnDef\n- Fires `sortChanged` event: `{column: string, direction: ''asc'' | ''desc''}`\n\n### Filtering\n- Global text search across specified fields or all columns\n- Debounced input (default 300ms) prevents excessive re-renders\n- Highlight matches with yellow background\n- Shows \"Found N matching records\" count\n- Configurable `filterFields` array to limit search scope\n- Fires `filterChanged` event: `{filterValue: string, matchingData: Array<object>}`\n\n### Pagination\n- Configurable page size (default 10, options: 5/10/20/50/100)\n- Shows \"X-Y of Z\" range display\n- Optional page size changer dropdown\n- Fires `pageChanged` event: `{pageNumber: number (0-based), visibleRows: Array<object>}`\n\n### Row Selection\nFour modes via `selectionMode` prop:\n\n1. **none** (default): No selection\n2. **checkbox**: Multi-select with checkboxes\n3. **radio**: Single-select with radio buttons\n4. **row**: Click anywhere on row to toggle selection\n\nFires `selectionChanged` event with full selected record objects.\n\n### Row Click & Record Opening\n**Priority order**:\n\n1. **If `onRowClick` provided**: Fires event with record, overrides default behavior\n2. **Else if `entityName` + `entityPrimaryKeys` + `callbacks.OpenEntityRecord` exist**:\n   - Extracts primary key values from record using `entityPrimaryKeys` field names\n   - Validates all key values exist (not null)\n   - Calls `callbacks.OpenEntityRecord(entityName, keyValues)`\n   - Use for 1:1 record-to-row scenarios only (not aggregated data)\n\n### Column Widths\n**Auto-fit mode** (`autoFitColumns={true}`, default):\n- Columns auto-size to fill container width\n- No horizontal scrolling\n\n**Fixed mode** (`autoFitColumns={false}`):\n- Intelligent width based on SQL type and field length:\n  - GUIDs: 280px\n  - Long text (varchar(max), nvarchar(max), length=-1, or >200 chars): 400px\n  - Variable char fields: Scale by length (50→100-200px, 100→250px, 200→300px)\n  - Dates: 160px\n  - Bit: 80px\n  - Int: 100px\n  - Decimal/Numeric: 120px\n  - Money: 130px\n- Horizontal scrolling enabled\n- Per-column `width` override in ColumnDef\n\n## Visual States\n\n### Loading\nShows spinner when `data === null` (use null for initial load, not empty array).\n\n### Empty\nShows \"No {entityName || ''records''} found\" message for empty datasets.\n\n### No Animations\nCSS overrides disable all Ant Design animations to prevent render loop detection issues.\n\n## Events\n\n1. **rowClick**: `(event: {record: object, cancel: boolean}) => void`\n   - Fired on row click with cancelable pattern\n   - Set `event.cancel = true` to prevent default OpenEntityRecord behavior\n\n2. **selectionChanged**: `({selectedRows: Array<object>}) => void`\n   - Fired when row selection changes\n\n3. **pageChanged**: `({pageNumber: number, visibleRows: Array<object>}) => void`\n   - Fired on page change with 0-based page number\n\n4. **sortChanged**: `({sortState: {column: string, direction: ''asc'' | ''desc''}}) => void`\n   - Fired when column sort changes\n\n5. **filterChanged**: `({filterValue: string, matchingData: Array<object>}) => void`\n   - Fired when filter text changes with all matching records\n","technicalDesign":"## Architecture\nReact functional component wrapping Ant Design Table 5.12.0 with MemberJunction metadata enhancements. **Note**: This describes internal implementation details. The public API uses `{field, header, render}`, not Ant Design''s `{dataIndex, title, key}`.\n\n## State Management (React Hooks)\n- **filterText** (string): Raw search input\n- **debouncedFilter** (string): Processed search term after 300ms delay\n- **selectedRowKeys** (array): Row selection state\n- **currentPage** (number): Pagination state\n- **sortConfig** (object): Sort state `{column, direction}`\n- **entityInfo** (object): Entity metadata from `utilities.md.Entities`\n- **expandedCells** (object): Tracks expanded long-text cells `{recordKey_fieldName: boolean}`\n\n## Initialization\n\n### Library Unwrapping\nUses `unwrapLibraryComponents(antd, ''Table'', ''Input'', ''Space'', ''Typography'', ''Tag'', ''Tooltip'')` to handle various Ant Design package formats (ESM/CJS/UMD).\n\n### Metadata Loading (useEffect)\nIf `entityName` provided:\n- Loads entity from `utilities.md.Entities`\n- Stores field metadata (Type, Length, DisplayName, ValueListType, EntityFieldValues)\n- Else sets `entityInfo = null`, uses basic type detection\n\n## Column Processing Pipeline (useMemo)\n\n### 1. Normalization\nAccepts `columns` as:\n- **String array**: `[''Name'', ''Price'']` → Normalizes to ColumnDef format\n- **ColumnDef objects**: `{field, header, render, width, sortable}`\n- **Auto-detection**: If omitted, discovers from `Object.keys(data[0])`, excludes ''key'' field\n\nHandles invalid configs with console warnings.\n\n### 2. Column Building\nConverts ColumnDef format (`{field, header}`) to Ant Design Table format internally:\n- **Alignment**: Based on SQL type (int/decimal/float/money/bit → right, others → left)\n- **Width calculation** (when `autoFitColumns=false`):\n  - GUIDs: 280px\n  - Long text (text type OR varchar(max) with length=-1 OR varchar >200): 400px\n  - Variable char: Scales by length (≤50→100-200px, ≤100→250px, ≤200→300px, else→350px)\n  - Dates: 160px\n  - Bit: 80px\n  - Int: 100px\n  - Decimal/numeric: 120px\n  - Money: 130px\n- **Override**: `colDef.width` if provided\n- **Sorter**: Creates function if `sortable` (string localeCompare, number subtraction, null handling)\n- **Render**: Priority: (1) Custom `colDef.render`, (2) Metadata-driven default\n\n### 3. Field Rendering Logic\nFor each cell:\n1. **Custom render**: If provided, call with `(value, record, fieldInfo)`\n2. **Null handling**: Return ''-''\n3. **Cell key**: Create unique key `$' + CAST(N'' AS NVARCHAR(MAX)) + N'{record.key/ID/id}_$' + CAST(N'' AS NVARCHAR(MAX)) + N'{fieldName}` for expansion tracking\n4. **Type-based formatting**:\n   - **date/time**: formatDate with locale (hour/minute)\n   - **bit**: Yes/No text\n   - **Value lists**: Tag component with `getValueColor(value, entityInfo)`\n   - **money**: Intl.NumberFormat USD currency\n   - **decimal/float**: toLocaleString with 2 decimals\n   - **int**: toLocaleString with commas\n5. **Long text handling** (if field is long text type AND length > `longTextThreshold`):\n   - **truncate**: substring + ''...''\n   - **expand**: Toggle on click, shows ''show more/less'' links, tracks state in `expandedCells`\n   - **tooltip**: Ant Tooltip wrapper\n   - **wrap**: whiteSpace:normal, wordBreak:break-word\n   - **none**: default\n6. **Filter highlighting**: If `debouncedFilter` exists, wrap matches in `Typography.Text mark`\n\n## Value List Coloring System\n\n### statusColorMap\n50+ predefined colors for common statuses:\n- active → #389e0d (green)\n- pending → #d48806 (orange)\n- failed → #a8071a (red)\n- processing → #096dd9 (blue)\n- etc.\n\n### fallbackColors\nArray of 50 distinct colors (purple, magenta, teal, indigo, vermillion, brown, etc.)\n\n### getValueColor Function\n1. Build `colorAssignments` Map\n2. Iterate `possibleValues` from entity metadata\n3. Assign `statusColorMap` color if exists, else next `fallbackColor`\n4. Ensures consistent colors per value across dataset\n5. Unknown values: Check `statusColorMap` first, then hash-based fallback index\n\n## Filter Debouncing (useEffect)\n- `setTimeout` with `filterDebounceTime` (300ms default)\n- Updates `debouncedFilter` after delay\n- Cleanup clears timer on unmount or input change\n\n## Filtered Data (useMemo)\nIf `filtering=false` or `!debouncedFilter`:\n- Return original `data`\n\nElse:\n- Determine `searchFields` (`filterFields` prop or all display fields)\n- Filter rows where any searchField value includes searchTerm (case-insensitive)\n- Handle null/undefined gracefully\n\n## Filter Change Effect (useEffect)\nFires `onFilterChanged` event with `{filterValue: debouncedFilter, matchingData: filteredData}`\n\n## Row Selection Config\nIf `selectionMode !== ''none''`:\n- Creates `rowSelection` object with:\n  - type: ''radio'' or ''checkbox''\n  - selectedRowKeys state\n  - onChange handler (updates state, fires `onSelectionChanged`)\n- For ''row'' mode: Adds `onSelect` handler\n\n## Pagination Config\nIf `paging=true`:\n- Creates pagination object:\n  - current: `currentPage`\n  - pageSize: From prop\n  - total: `filteredData.length`\n  - showSizeChanger: false\n  - showTotal: Formatter function\n  - onChange: Updates `currentPage`, fires `onPageChanged` with 0-based page number and visible rows slice\n\n## Sort Handling\n`handleTableChange` extracts sorter from Ant Table onChange:\n- Updates `sortConfig` state\n- Fires `onSortChanged` with `{sortState: {column: sorter.field, direction: sorter.order === ''ascend'' ? ''asc'' : ''desc''}}`\n\n## Row Click Handling\n`handleRowClick` with priority logic:\n1. If `onRowClick` provided: Call with record and return early (custom handler overrides)\n2. Else if `entityName` AND `entityPrimaryKeys` AND `callbacks.OpenEntityRecord` exist:\n   - Maps `entityPrimaryKeys` to key-value pairs `[{FieldName, Value}]`\n   - Extracts values from record\n   - Checks all key values exist (!=null)\n   - If yes: Calls `callbacks.OpenEntityRecord(entityName, keyValues)`\n   - Else: Logs warning\n3. Wrapped in try/catch with error logging\n\n## Data with Keys (useMemo)\nMaps `filteredData` to add unique `key` prop:\n- Uses existing key/ID/id or falls back to index\n- Required for Ant Design Table row selection\n\n## CSS Style Injection\nDisables all Ant Design animations to prevent render loop detection:\n```css\n.data-grid-component * {\n  animation: none !important;\n  transition: none !important;\n  animation-duration: 0s !important;\n  transition-duration: 0s !important;\n}\n```\n\n## Render Output\nWrapper div with `.data-grid-component` class:\n\n1. **Search UI** (if `filtering=true`):\n   - Ant Input.Search with value/onChange/allowClear/onClear\n   - Placeholder shows filterFields or ''all fields''\n   - Full width style\n   - Text showing \"Found N matching records\" if `debouncedFilter` exists\n\n2. **Ant Table**:\n   - columns: `tableColumns`\n   - dataSource: `dataWithKeys`\n   - rowSelection: If enabled\n   - pagination: If enabled\n   - onChange: `handleTableChange` for sort\n   - scroll: `{x: ''max-content''}` only if `autoFitColumns=false`\n   - loading: true only when `data===null`\n   - locale: emptyText uses `entityName` if provided\n   - size: ''middle''\n   - onRow: Returns object with onClick handler and cursor style\n\n## Performance Optimizations\n- useMemo for column building, filtered data, data with keys\n- useCallback for event handlers (prevents re-renders)\n- Debounced filter input (prevents excessive re-renders)\n- CSS transitions disabled (prevents render loop)\n","dataRequirements":{"mode":"views","description":"Component is data-agnostic and works with any entity data passed via props"},"typeDefinitions":{"ColumnDef":{"description":"Column definition object for advanced column configuration","properties":{"field":{"type":"string","required":true,"description":"Field name from data object"},"header":{"type":"string","required":false,"description":"Display header text (defaults to field DisplayName or field name)"},"render":{"type":"function","signature":"(value: any, record: object, fieldInfo?: object) => ReactNode","required":false,"description":"Custom render function for cell content"},"width":{"type":"string | number","required":false,"description":"Column width (e.g., ''200px'' or 200)"},"sortable":{"type":"boolean","required":false,"description":"Override global sorting setting for this column"}}}},"properties":[{"name":"data","type":"Array<object>","description":"Array of records to display. Can be from any source: single entity, joined tables, aggregated results, or any array of objects.","required":true},{"name":"entityName","type":"string","description":"Optional entity name for metadata lookup (enables smart formatting for dates, money, value lists) and OpenEntityRecord integration. If omitted, component uses basic type detection and does not support record opening.","required":false},{"name":"entityPrimaryKeys","type":"Array<string>","description":"Array of field names that constitute the primary key(s). Used for two purposes: (1) React row keys — ensures unique keys per row, which is important for client-side joins where row.ID may not be unique, and (2) OpenEntityRecord integration — clicking a row opens the entity record using these fields. Example: [''ID''] for single key, [''OrderID'', ''LineNumber''] for composite key.","required":false,"exampleValue":"[\"ID\"]","constraints":[{"type":"subset-of-entity-fields","dependsOn":"entityName","description":"When entityName is provided, validates that primary key field names exist on the specified entity","config":{"allowWildcard":false,"caseSensitive":true},"errorTemplate":"Primary key field ''{field}'' does not exist on entity ''{entityName}''"}]},{"name":"columns","type":"Array<string | ColumnDef>","description":"Array of column definitions. Can be simple strings (field names) for default behavior, or ColumnDef objects for advanced configuration. If not provided, all fields will be displayed. When using ColumnDef objects, the ''field'' property is validated against entity fields.","required":false,"exampleValue":"[\"Name\", { field: \"Price\", header: \"Unit Price\", render: (v) => `$$' + CAST(N'' AS NVARCHAR(MAX)) + N'{v}`, width: \"120px\", sortable: true }]","constraints":[{"type":"subset-of-entity-fields","dependsOn":"entityName","description":"When entityName is provided, validates that column field names (strings or ColumnDef.field properties) exist on the specified entity","config":{"allowWildcard":false,"caseSensitive":false},"errorTemplate":"Column field ''{field}'' does not exist on entity ''{entityName}''"}]},{"name":"sorting","type":"boolean","description":"Enable/disable column sorting","required":false,"defaultValue":true},{"name":"paging","type":"boolean","description":"Enable/disable pagination","required":false,"defaultValue":true},{"name":"pageSize","type":"number","description":"Number of rows per page when paging is enabled","required":false,"defaultValue":20},{"name":"showPageSizeChanger","type":"boolean","description":"Show the page size selector when paging is enabled","required":false,"defaultValue":true},{"name":"filtering","type":"boolean","description":"Enable/disable text filtering","required":false,"defaultValue":true},{"name":"highlightFilterMatches","type":"boolean","description":"Highlight matching text when filtering","required":false,"defaultValue":true},{"name":"filterFields","type":"Array<string>","description":"Fields to search when filtering. If not specified, searches all fields","required":false,"constraints":[{"type":"subset-of-entity-fields","dependsOn":"entityName","description":"When entityName is provided, validates that filter field names exist on the specified entity","config":{"allowWildcard":false,"caseSensitive":false},"errorTemplate":"Filter field ''{field}'' does not exist on entity ''{entityName}''"}]},{"name":"filterDebounceTime","type":"number","description":"Debounce time in ms for filter input","required":false,"defaultValue":300},{"name":"selectionMode","type":"''none'' | ''checkbox'' | ''radio'' | ''row''","description":"Row selection mode: ''none'', ''checkbox'', ''radio'', or ''row''","required":false,"defaultValue":"none","possibleValues":["none","checkbox","radio","row"]},{"name":"longTextDisplay","type":"''truncate'' | ''expand'' | ''tooltip'' | ''wrap'' | ''none''","description":"How to display long text that exceeds the threshold: ''truncate'' shows ellipsis, ''expand'' allows click to expand/collapse, ''tooltip'' shows full text on hover, ''wrap'' shows all text with wrapping, ''none'' uses default behavior","required":false,"defaultValue":"expand","possibleValues":["truncate","expand","tooltip","wrap","none"]},{"name":"longTextThreshold","type":"number","description":"Number of characters before long text display behavior is triggered","required":false,"defaultValue":100},{"name":"autoFitColumns","type":"boolean","description":"When true, columns auto-fit to container width. When false, columns use fixed widths with horizontal scrolling","required":false,"defaultValue":true}],"events":[{"name":"rowClick","description":"Fired when a row is clicked. Uses cancelable event pattern - set event.cancel = true to prevent default OpenEntityRecord behavior.","parameters":[{"name":"event","type":"{ record: object, cancel: boolean }","description":"Event object containing the clicked row record and cancel flag. Set cancel = true to prevent default behavior (OpenEntityRecord when entityName and entityPrimaryKeys are provided)."}]},{"name":"selectionChanged","description":"Fired when row selection changes. Callback receives a single object with a selectedRows property.","parameters":[{"name":"event","type":"{ selectedRows: Array<object> }","description":"Object containing the array of selected record objects"}]},{"name":"pageChanged","description":"Fired when page changes. Callback receives a single object with pageNumber, pageSize, and visibleRows.","parameters":[{"name":"event","type":"{ pageNumber: number, pageSize: number, visibleRows: Array<object> }","description":"Object with 0-based pageNumber, current pageSize, and the array of records visible on the new page"}]},{"name":"sortChanged","description":"Fired when sort configuration changes. Callback receives a single object with a sortState property.","parameters":[{"name":"event","type":"{ sortState: { column: string, direction: ''asc'' | ''desc'' } }","description":"Object with sortState containing the column name and sort direction"}]},{"name":"filterChanged","description":"Fired when filter changes. Callback receives a single object with filterValue and matchingData.","parameters":[{"name":"event","type":"{ filterValue: string, matchingData: Array<object> }","description":"Object with the current filter text and array of all matching records"}]}],"libraries":[{"name":"antd","version":"5.12.0","globalVariable":"antd"}],"dependencies":[],"code":"function DataGrid({\n  data,\n  entityName,\n  entityPrimaryKeys,\n  columns, // Array of column definitions: [{field: ''Name'', header: ''Product Name'', render: fn, width: ''200px'', sortable: true}]\n  sorting = true,\n  paging = true,\n  pageSize = 20,\n  showPageSizeChanger = true,\n  filtering = true,  // Changed default to true\n  highlightFilterMatches = true,\n  filterFields,\n  filterDebounceTime = 300,\n  selectionMode = ''none'',\n  longTextDisplay = ''expand'', // Options: ''truncate'', ''expand'', ''tooltip'', ''wrap'', ''none''\n  longTextThreshold = 100, // Characters before truncation\n  autoFitColumns = true, // Auto-fit columns to container width vs fixed widths with scroll\n  onSelectionChanged,\n  onPageChanged,\n  onSortChanged,\n  onFilterChanged,\n  onRowClick,\n  utilities,\n  styles,\n  components,\n  callbacks,\n  savedUserSettings,\n  onSaveUserSettings\n}) {\n  // Always use the MJ unwrapLibraryComponents function to get components from global libraries like antd, this ensures\n  // that various library build/package formats are handled correctly and transparently for your code!\n  const { Table, Input, Space, Typography, Tag, Tooltip } = unwrapLibraryComponents(antd, ''Table'', ''Input'', ''Space'', ''Typography'', ''Tag'', ''Tooltip'');\n  const { Search } = Input;\n  const { Text } = Typography;\n  const [filterText, setFilterText] = React.useState('''');\n  const [debouncedFilter, setDebouncedFilter] = React.useState('''');\n  const [selectedRowKeys, setSelectedRowKeys] = React.useState([]);\n  const [currentPage, setCurrentPage] = React.useState(1);\n  const [currentPageSize, setCurrentPageSize] = React.useState(pageSize);\n  const [sortConfig, setSortConfig] = React.useState(null);\n  const [entityInfo, setEntityInfo] = React.useState(null);\n  const [expandedCells, setExpandedCells] = React.useState({}); // Track which cells are expanded\n\n\n  // Update current page size when pageSize prop changes\n  React.useEffect(() => {\n    setCurrentPageSize(pageSize);\n  }, [pageSize]);\n\n  // Load entity metadata if we have an entity name\n  React.useEffect(() => {\n    if (entityName && utilities?.md?.Entities) {\n      const entity = utilities.md.Entities.find(e => e.Name === entityName);\n      setEntityInfo(entity || null);\n    } else {\n      setEntityInfo(null);\n    }\n  }, [entityName, utilities]);\n  \n  // Helper function to format dates\n  const formatDate = (value) => {\n    if (!value) return ''-'';\n    try {\n      const date = new Date(value);\n      if (isNaN(date.getTime())) return value; // Invalid date, return as-is\n      // Format as YYYY-MM-DD HH:MM\n      return date.toLocaleString(''en-US'', {\n        year: ''numeric'',\n        month: ''2-digit'',\n        day: ''2-digit'',\n        hour: ''2-digit'',\n        minute: ''2-digit''\n      });\n    } catch {\n      return value;\n    }\n  };\n  \n  // Color mapping for common status values (darker for better contrast with white text)\n  const statusColorMap = {\n    // Green colors for positive states\n    active: ''#389e0d'',      // darker green\n    approved: ''#52c41a'',    // green\n    complete: ''#237804'',    // dark green\n    completed: ''#135200'',   // very dark green\n    success: ''#3f6600'',     // olive green\n    successful: ''#5b8c00'',  // light olive\n    enabled: ''#7cb305'',     // lime\n    published: ''#a0d911'',   // light lime\n    \n    // Red colors for negative states\n    inactive: ''#cf1322'',    // darker red\n    rejected: ''#f5222d'',    // red\n    failed: ''#a8071a'',      // dark red\n    error: ''#820014'',       // very dark red\n    disabled: ''#ff4d4f'',    // light red\n    cancelled: ''#ff7875'',   // salmon\n    canceled: ''#ff9c9c'',    // light salmon\n    terminated: ''#873800'',  // burnt orange\n    expired: ''#ad4e00'',     // dark orange\n    deprecated: ''#d4380d'',  // rust orange\n    \n    // Yellow/Orange for pending states\n    pending: ''#d48806'',     // darker orange\n    paused: ''#fa8c16'',      // orange\n    temporary: ''#faad14'',   // gold\n    draft: ''#d4b106'',       // dark gold\n    review: ''#ad8b00'',      // darker gold\n    waiting: ''#ffc53d'',     // light gold\n    \n    // Blue for informational states\n    processing: ''#096dd9'',  // darker blue\n    running: ''#1890ff'',     // blue\n    inprogress: ''#0050b3'',  // dark blue\n    ''in progress'': ''#003a8c'', // very dark blue\n    ''in-progress'': ''#40a9ff'' // light blue\n  };\n  \n  // 50 distinct colors for value lists (excluding colors used in statusColorMap)\n  // These are carefully selected to be visually distinct from each other\n  const fallbackColors = [\n    ''#722ed1'', // purple\n    ''#9254de'', // light purple\n    ''#531dab'', // dark purple\n    ''#391085'', // very dark purple\n    ''#b37feb'', // lavender\n    \n    ''#c41d7f'', // magenta\n    ''#eb2f96'', // pink\n    ''#f759ab'', // light pink\n    ''#9e1068'', // dark magenta\n    ''#780650'', // very dark magenta\n    \n    ''#08